// src/game/logic.js
// 《巴士大疏通》核心逻辑 —— 纯数据模型，不依赖 DOM。

export const COLORS = ['red','blue','green','yellow','purple','cyan','orange'];

export const DIRECTION_AXIS = { right:'h', left:'h', up:'v', down:'v' };

// 巴士生命周期：board(棋盘上) -> loading(接客位) -> departed(已发车离场)

export function cellsOfBus(bus) {
  const cells = [];
  if (bus.dir === 'left' || bus.dir === 'right') {
    for (let i = 0; i < bus.len; i++) cells.push({ x: bus.x + i, y: bus.y });
  } else {
    for (let i = 0; i < bus.len; i++) cells.push({ x: bus.x, y: bus.y + i });
  }
  return cells;
}

export function exitPathOfBus(bus, grid) {
  // 车头到棋盘边缘之间需要清空的格子（不含自身）
  const cells = [];
  if (bus.dir === 'right') { for (let x = bus.x + bus.len; x < grid.cols; x++) cells.push({x, y: bus.y}); }
  else if (bus.dir === 'left') { for (let x = 0; x < bus.x; x++) cells.push({x, y: bus.y}); }
  else if (bus.dir === 'down') { for (let y = bus.y + bus.len; y < grid.rows; y++) cells.push({x: bus.x, y}); }
  else if (bus.dir === 'up') { for (let y = 0; y < bus.y - bus.len + 1; y++) cells.push({x: bus.x, y}); }
  return cells;
}
```

等等 up 的路径：bus 占 (x, y-len+1 .. y)，车头在 y-len+1，路径是 y-len .. 0 即 0..y-len。`for (let y = 0; y <= bus.y - bus.len; y++)`。对。

