export function buildOccupancy(state) {
  const map = new Map();
  for (const bus of Object.values(state.buses)) {
    if (bus.status !== 'board') continue;
    for (const c of cellsOfBus(bus)) map.set(c.x + ',' + c.y, bus.id);
  }
  return map;
}
