export function initializeLevel(level) {
  const buses = {};
  for (const b of level.buses) {
    buses[b.id] = {
      id: b.id, color: b.color, len: b.len, dir: b.dir,
      x: b.dir==='left'||b.dir==='right' ? b.x : b.x,
      y: b.y,
      capacity: b.capacity ?? b.len,
      status: 'board', slotIndex: null, passengers: 0,
    };
  }
  return {
    levelId: level.id,
    grid: { cols: level.grid.cols, rows: level.grid.rows },
    slotCount: level.slots,
    slots: Array.from({length: level.slots}, (_, i) => ({ index: i, busId: null })),
    buses,
    queue: level.queue.map(c => ({ color: c })),  // index 0 = 队首
    moveCount: 0,
    status: 'playing',  // 'playing' | 'won' | 'lost'
  };
}
```

validateMove(state, busId):
```js
export function validateMove(state, busId) {
  const bus = state.buses[busId];
  if (!bus || state.status !== 'playing') return { ok: false, reason: 'not-playing' };
  if (bus.status !== 'board') return { ok: false, reason: 'not-on-board' };
  const occ = buildOccupancy(state);
  for (const c of exitPathOfBus(bus, state.grid)) {
    const blocker = occ.get(c.x + ',' + c.y);
    if (blocker) return { ok: false, reason: 'blocked', blockerId: blocker, blockerCell: c };
  }
  if (!hasFreeSlot(state)) return { ok: false, reason: 'no-slot' };
  return { ok: true };
}
```

moveBus(state, busId) → { ok, reason?, events }：
```js
export function moveBus(state, busId) {
  const check = validateMove(state, busId);
  if (!check.ok) return { ok: false, reason: check.reason, blockerId: check.blockerId };
  const bus = state.buses[busId];
  const exitCells = cellsOfBus(bus).slice();  // 动画用
  const dir = bus.dir;
  const slotIndex = firstFreeSlot(state);
  state.slots[slotIndex].busId = busId;
  bus.status = 'loading';
  bus.slotIndex = slotIndex;
  bus.x = null; bus.y = null;  // 防止旧坐标被误用 —— 嗯，cellsOfBus 会崩。风险。
  state.moveCount++;
  return { ok: true, events: [
    { type: 'exit', busId, dir, cells: exitCells },
    { type: 'arrive', busId, slotIndex },
  ]};
}
```

