export function boardPassengers(state) {
  const events = [];
  while (state.status === 'playing' && state.queue.length > 0) {
    const next = state.queue[0];
    const busId = findBoardableBus(state, next.color);
    if (busId == null) break;
    const bus = state.buses[busId];
    state.queue.shift();
    bus.passengers++;
    events.push({ type: 'board', busId, slotIndex: bus.slotIndex, color: next.color });
    // 满载会由 departReady 处理（先返回，让 UI 逐段播放）
    if (bus.passengers >= bus.capacity) break;  // 满了，先发车再继续（事件顺序更自然）
  }
  return events;
}
```
嗯，board 循环里满了 break，让 departReady 先走。等等如果没满但队首变了不能上 → break。OK。

departReady(state)：
```js
export function departReady(state) {
  const events = [];
  for (const slot of state.slots) {
    if (slot.busId == null) continue;
    const bus = state.buses[slot.busId];
    if (canDepart(state, bus)) {
      slot.busId = null;
      bus.status = 'departed';
      bus.slotIndex = null;
      events.push({ type: 'depart', busId: bus.id, passengers: bus.passengers, capacity: bus.capacity, color: bus.color });
    }
  }
  return events;
}

function canDepart(state, bus) {
  if (bus.passengers >= bus.capacity) return true;
  const remaining = state.queue.some(p => p.color === bus.color);
  return !remaining;
}
```

