export function checkLose(state) {
  if (state.status !== 'playing') return false;
  // 必须在稳定态调用（boardPassengers/departReady 都无事件）
  if (state.queue.length === 0) return false; // 队列空时要么 win 要么还能推进
  // 队首必然无法上车（稳定态）→ 检查玩家是否还有合法操作
  if (freeSlotCount(state) > 0) {
    const occ = buildOccupancy(state);
    for (const bus of Object.values(state.buses)) {
      if (bus.status !== 'board') continue;
      if (pathClear(bus, state.grid, occ)) return false; // 还有车能出来 → 不算输
    }
  }
  state.status = 'lost';
  return true;
}
```
等等，"queue 空 return false" 对吗？queue 空 + slots 有车（待发）→ advance 会 depart。稳定态 queue 空 → slots 空 → checkWin 会先触发。checkLose 在 checkWin 之后调用的话 status 已 'won' → false ✓。如果 checkWin false（queue 非空）→ checkLose 检查。好。

另外还有个 subtle：queue 非空 + slots 空 + 棋盘无可出车（全被挡）→ 死锁 ✓ covered（freeSlot>0 但无 clear path → lost）。

还有 queue 非空 + slots 有等待车 + freeSlot 0 → 无车能出（no-slot）→ 死锁 ✓。

还有个我想加的：棋盘上根本没有车（全 departed）但 queue 非空 → freeSlot>0 但没有 board 车 → 循环不 return false → lost ✓。好。

