```js
// BFS 求解器：用与游戏完全相同的逻辑验证关卡
import { initializeLevel, moveBus, boardPassengers, departReady, checkWin } from './logic.js';
import { LEVELS } from './levels.js';

function stateKey(state) {
  const buses = Object.values(state.buses)
    .map(b => `${b.id}:${b.status}:${b.slotIndex ?? '-'}:${b.passengers}`)
    .sort().join('|');
  const queue = state.queue.map(p => p.color[0]).join('');
  const slots = state.slots.map(s => s.busId ?? '.').join(',');
  return buses + '#' + queue + '#' + slots;
}

function settleAll(state) {
  const events = [];
  for (;;) {
    const b = boardPassengers(state);
    const d = departReady(state);
    events.push(...b, ...d);
    if (b.length === 0 && d.length === 0) return events;
  }
}

function solve(level) {
  const init = initializeLevel(level);
  // BFS over click sequences
  const start = { state: init, path: [] };
  const seen = new Set([stateKey(init)]);
  const queue = [start];
  while (queue.length) {
    const { state, path } = queue.shift();
    if (checkWin(state)) return { solvable: true, path };
    // 注意 checkWin 会改 status；copy state? 
    ...
  }
}
```

问题：checkWin/checkLose 有副作用（set status）。BFS 里 state 是可变的且被 mutation……moveBus 等都 mutate state。BFS 需要每次分支前 deep copy state。用 structuredClone（node 22 有）。✓ 每个队列节点存 {state, path}；扩展时 clone。

checkWin 副作用：clone 后 checkWin 设 status won 没关系（该分支返回）。但注意：分支里 settle 后 checkWin——如果 win 了就返回路径。没 win 继续扩展。status 变化只在 win/lose。lose 状态下 moveBus validateMove 会拒绝（not-playing）→ 该分支无操作 → 剪枝（不需要显式，只是无子节点）。

BFS：
```js
for each bus in state.buses (status board):
  const child = structuredClone(state);
  const res = moveBus(child, busId);
  if (!res.ok) continue;
  settleAll(child);
  // lose check: checkLose(child) → 若 lose，跳过（无子）
  const key = stateKey(child);
  if (seen.has(key)) continue;
  seen.add(key);
  if (checkWin(child)) return path+busId
  queue.push({state: child, path: [...path, busId]});
```

