controller 的 settle 循环：
```js
async function runSettle() {
  for (;;) {
    const boardEvs = boardPassengers(state)
    for (const ev of boardEvs) await animateBoard(ev)
    if (boardEvs.length) { renderer.renderQueue(state); renderer.renderHud(state) }
    const depEvs = departReady(state)
    for (const ev of depEvs) await animateDepart(ev)
    if (depEvs.length) renderer.renderSlots(state)
    if (!boardEvs.length && !depEvs.length) break
  }
}
```
