renderHud 不用（moveCount 不变）。

onBusClick：
```js
async function onBusClick(busId) {
  if (locked || !state || state.status !== 'playing') return
  const res = moveBus(state, busId)   // 内部 validate
  if (!res.ok) {
    if (res.reason === 'blocked') feedbackBlocked(busId, res.blockerId)
    else if (res.reason === 'no-slot') toast('接客位已满！等巴士满载发车腾出空位')
    return
  }
  locked = true
  renderer.renderHud(state)
  for (const ev of res.events) {
    if (ev.type === 'exit') await animateExit(ev)
    else if (ev.type === 'arrive') { renderer.renderSlots(state); await sleep(300) }
  }
  renderer.renderBoard(state)  // 移除已驶出的巴士
  await runSettle()
  if (checkWin(state)) { await sleep(300); showWin(); return }  // locked 保持 true
  if (checkLose(state)) { await sleep(300); showLose(); return }
  locked = false
  if (pendingRelayout) { pendingRelayout = false; renderer.renderAll(state, level) }
}
```

