/* ===== 《巴士大疏通》样式 ===== */

:root {
  --bg: #f2ead9;
  --card: #fffdf7;
  --ink: #38301f;
  --ink-soft: #8f8367;
  --accent: #ff9f43;
  --accent-deep: #ef8a2a;
  --board-bg: #dce9e0;
  --cell-line: #c3d4c8;
  --danger: #e8554d;

  --bus-red: #e8554d;
  --bus-blue: #4d8fe8;
  --bus-green: #43b96b;
  --bus-purple: #9a6bd6;
  --bus-cyan: #35bdc2;
  --bus-orange: #ef8a2a;
  --bus-yellow: #e9c23c;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; padding: 0; height: 100%; }
body {
  background: var(--bg);
  color: var(--ink);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  display: flex; justify-content: center;
  user-select: none; -webkit-user-select: none;
}

#app {
  width: 100%; max-width: 540px; height: 100dvh;
  display: flex; flex-direction: column;
  position: relative; overflow: hidden;
}

.hidden { display: none !important; }

/* ===== 通用按钮 ===== */
.btn {
  border: none; cursor: pointer; font-family: inherit;
  border-radius: 12px; font-size: 15px; font-weight: 600;
  padding: 10px 18px; color: #fff;
  transition: transform .12s, filter .12s, box-shadow .12s;
}
.btn:active { transform: scale(.95); filter: brightness(.95); }
.btn-primary { background: linear-gradient(180deg, var(--accent), var(--accent-deep)); box-shadow: 0 4px 0 #c96f14; }
.btn-primary:active { box-shadow: 0 1px 0 #c96f14; }
.btn-ghost { background: #efe6d0; color: var(--ink); box-shadow: 0 3px 0 #d8cba9; }
.btn-ghost:active { box-shadow: 0 1px 0 #d8cba9; }
.btn-big { font-size: 19px; padding: 14px 46px; border-radius: 16px; }

/* ===== 开始页 ===== */
#screen-start { flex: 1; display: flex; align-items: center; justify-content: center; padding: 24px; }
.start-card {
  background: var(--card); border-radius: 26px; padding: 34px 26px;
  text-align: center; width: min(100%, 380px);
  box-shadow: 0 10px 30px rgba(90, 70, 20, .12);
}
.start-buses { display: flex; gap: 10px; justify-content: center; margin-bottom: 18px; }
.mini-bus { width: 56px; height: 24px; border-radius: 8px; position: relative; }
.mini-bus::after {
  content: ""; position: absolute; right: 4px; top: 3px; bottom: 3px; width: 10px;
  background: rgba(255,255,255,.8); border-radius: 3px;
}
.game-title { font-size: 40px; margin: 6px 0 8px; letter-spacing: 2px; color: var(--ink); }
.game-sub { color: var(--ink-soft); margin: 0 0 22px; font-size: 15px; }
.start-rules { list-style: none; padding: 0; margin: 0 0 26px; text-align: left; }
.start-rules li {
  display: flex; align-items: center; gap: 10px;
  background: #f7f1e2; border-radius: 12px; padding: 10px 12px; margin-bottom: 9px;
  font-size: 14px; line-height: 1.45; color: #5c523a;
}
.rule-ico { font-size: 20px; flex: none; }
.start-foot { color: var(--ink-soft); font-size: 12px; margin: 14px 0 0; }

/* ===== 游戏页布局 ===== */
#screen-game {
  flex: 1; display: flex; flex-direction: column; gap: 8px;
  padding: 10px 12px calc(12px + env(safe-area-inset-bottom));
  min-height: 0;
}

#hud {
  display: flex; align-items: center; gap: 8px;
  background: var(--card); border-radius: 14px; padding: 9px 12px;
  box-shadow: 0 3px 10px rgba(90, 70, 20, .08);
}
.hud-left { font-weight: 700; font-size: 16px; }
.hud-mid { flex: 1; color: var(--ink-soft); font-size: 13px; text-align: center; }
.hud-right { display: flex; gap: 8px; }
.hud-right .btn { padding: 6px 12px; font-size: 13px; }

.area-label { font-size: 12.5px; font-weight: 700; color: #6d6146; margin: 2px 2px 5px; }
.area-sub { font-weight: 400; color: var(--ink-soft); font-size: 11.5px; }

/* --- 候车队列 --- */
#queue-area { flex: none; }
#queue {
  display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
  background: var(--card); border-radius: 14px; padding: 10px;
  min-height: 56px; box-shadow: 0 3px 10px rgba(90,70,20,.06);
}
.queue-empty { color: var(--ink-soft); font-size: 13px; width: 100%; text-align: center; }

.passenger {
  width: 30px; height: 36px; position: relative; border-radius: 8px;
  background: var(--pc, #999);
  box-shadow: inset 0 -3px 0 rgba(0,0,0,.15);
  transition: transform .15s;
}
.passenger::before { /* 头 */
  content: ""; position: absolute; top: 2px; left: 50%; transform: translateX(-50%);
  width: 14px; height: 12px; border-radius: 7px 7px 5px 5px; background: #ffe3c4;
}
.passenger::after { /* 眼睛 */
  content: ""; position: absolute; top: 5px; left: 50%; transform: translateX(-50%);
  width: 8px; height: 3px;
  background:
    radial-gradient(circle, #3a3020 1.2px, transparent 1.6px) 0 0 / 4px 3px no-repeat,
    radial-gradient(circle, #3a3020 1.2px, transparent 1.6px) 100% 0 / 4px 3px no-repeat;
}
.passenger.head {
  transform: scale(1.14);
  box-shadow: 0 0 0 3px #fff, 0 0 0 6px var(--accent), inset 0 -3px 0 rgba(0,0,0,.15);
}
.passenger.head::marker { content: none; }
#queue::before {
  content: "▶ 先上"; color: var(--accent-deep); font-size: 11px; font-weight: 700;
  margin-right: 4px;
}

/* --- 停车场 --- */
#board-area { flex: 1; display: flex; flex-direction: column; min-height: 0; }
#board-wrap { flex: 1; min-height: 0; display: flex; justify-content: center; align-items: center; }
#board { position: relative; background: var(--board-bg); border-radius: 12px; }
.cell {
  position: absolute;
  border-radius: 4px;
  box-shadow: inset 0 0 0 1px var(--cell-line);
}

/* --- 巴士 --- */
.bus {
  position: absolute; cursor: pointer;
  transition: filter .15s;
  z-index: 2;
}
.bus:hover { filter: brightness(1.07); }
.bus:active { filter: brightness(1.12); }
.bus-inner {
  position: absolute; inset: 2px; border-radius: 7px;
  background: var(--bc);
  box-shadow: inset 0 -4px 0 rgba(0,0,0,.14), inset 0 3px 0 rgba(255,255,255,.28);
}
.bus-cab {
  position: absolute; background: rgba(255,255,255,.85);
  border-radius: 4px;
}
.dir-right .bus-cab, .dir-left .bus-cab { top: 12%; bottom: 12%; width: 16%; }
.dir-right .bus-cab { right: 5%; }
.dir-left  .bus-cab { left: 5%; }
.dir-down  .bus-cab, .dir-up .bus-cab { left: 12%; right: 12%; height: 16%; }
.dir-down  .bus-cab { bottom: 5%; }
.dir-up    .bus-cab { top: 5%; }

.bus-dots {
  position: absolute; inset: 0; display: flex; gap: 3px;
  align-items: center; justify-content: center;
}
.dir-up .bus-dots, .dir-down .bus-dots { flex-direction: column; }
.bus-dots i {
  width: 7px; height: 7px; border-radius: 50%;
  background: rgba(255,255,255,.35);
}
.bus-dots i.filled { background: #fff; box-shadow: 0 0 4px rgba(255,255,255,.8); }
.bus-cap {
  position: absolute; right: 5px; bottom: 4px;
  font-size: 11px; font-weight: 800; color: #fff;
  text-shadow: 0 1px 2px rgba(0,0,0,.4); pointer-events: none;
}

/* --- 接客位 --- */
#slots-area { flex: none; }
#slots { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.slot {
  width: 92px; height: 66px; border-radius: 14px;
