/* --- 颜色 --- */
.c-red    { --bc: var(--bus-red); --pc: var(--bus-red); }
.c-blue   { --bc: var(--bus-blue); --pc: var(--bus-blue); }
.c-green  { --bc: var(--bus-green); --pc: var(--bus-green); }
