#toast {
  position: absolute; top: 64px; left: 50%; transform: translateX(-50%);
  background: rgba(45, 38, 24, .92); color: #fff;
  padding: 9px 16px; border-radius: 12px; font-size: 13.5px;
  max-width: 86%; text-align: center; z-index: 60;
  animation: toastIn .25s;
  box-shadow: 0 6px 18px rgba(0,0,0,.25);
}
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -8px); } }

/* --- 结算覆盖层 --- */
.overlay {
  position: absolute; inset: 0; z-index: 50;
  background: rgba(40, 32, 16, .45); backdrop-filter: blur(2px);
  display: flex; align-items: center; justify-content: center;
  animation: fadeIn .25s;
}
.overlay-card {
  background: var(--card); border-radius: 22px; padding: 30px 26px;
  width: min(86%, 360px); text-align: center;
  box-shadow: 0 14px 40px rgba(50, 40, 10, .3);
  animation: popIn .35s;
}
.overlay-icon { font-size: 52px; line-height: 1; }
.overlay-card h2 { margin: 12px 0 8px; font-size: 26px; }
#overlay-text { color: var(--ink-soft); font-size: 14.5px; line-height: 1.6; margin: 0 0 22px; }
.overlay-btns { display: flex; gap: 10px; justify-content: center; }

/* ===== 动画 ===== */
@keyframes fadeIn { from { opacity: 0; } }
@keyframes popIn { from { transform: scale(.6); opacity: 0; } }
.pop-in { animation: popIn .3s cubic-bezier(.2, 1.4, .5, 1); }

@keyframes bump { 50% { transform: scale(1.18); } }
.anim-bump { animation: bump .3s; }

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-8px); }
  40% { transform: translateX(8px); }
  60% { transform: translateX(-6px); }
  80% { transform: translateX(6px); }
}
.anim-shake { animation: shake .45s; }

@keyframes blockFlash {
  0%, 100% { box-shadow: none; }
  50% { box-shadow: 0 0 0 4px rgba(232, 85, 77, .85); border-radius: 7px; }
}
.anim-flash { animation: blockFlash .45s 2; }

.bus.anim-exit {
  transition: transform .42s cubic-bezier(.5, 0, 1, 1), opacity .42s;
  z-index: 5; opacity: .85;
}
.slot-bus.anim-depart {
  transition: transform .45s ease-in, opacity .45s;
  z-index: 3;
}
.passenger.flying {
  position: fixed; z-index: 99; margin: 0;
  transition: left .3s ease-in, top .3s ease-in, transform .3s, opacity .3s;
  pointer-events: none;
}

/* ===== 桌面适配 ===== */
@media (min-width: 700px) {
  #app { box-shadow: 0 0 40px rgba(80, 60, 20, .15); }
  .game-title { font-size: 46px; }
}

/**
 * 渲染层：把 state 映射为 DOM。
 * - 幂等：可反复调用，结果一致（每次全量重建，棋盘规模小无性能问题）；
 * - 只读：绝不修改游戏状态；
 * - 与逻辑层仅通过 state（只读）与 data-* 属性交互。
 */

export function createRenderer() {
  const $ = (id) => document.getElementById(id);
  const boardEl = $('board');
  const queueEl = $('queue');
  const slotsEl = $('slots');
  const hudLevelEl = $('hud-level');
  const hudMovesEl = $('hud-moves');
  const boardWrapEl = $('board-wrap');

  let cell = 40;

  /* ---------- HUD ---------- */
  function renderHud(state, level) {
    hudLevelEl.textContent = `第 ${level.id} 关 · ${level.name}`;
    hudMovesEl.textContent = `操作 ${state.moveCount}`;
  }

  /* ---------- 停车场 ---------- */
  function renderBoard(state) {
    const availW = boardWrapEl.clientWidth - 4;
    const availH = boardWrapEl.clientHeight - 4;
    cell = Math.max(22, Math.floor(Math.min(availW / state.grid.cols, availH / state.grid.rows)));
    const w = cell * state.grid.cols;
    const h = cell * state.grid.rows;
    boardEl.style.width = `${w}px`;
    boardEl.style.height = `${h}px`;

    boardEl.innerHTML = '';
    for (let r = 0; r < state.grid.rows; r++) {
      for (let c = 0; c < state.grid.cols; c++) {
        const g = document.createElement('div');
        g.className = 'cell';
        g.style.left = `${c * cell}px`;
        g.style.top = `${r * cell}px`;
        g.style.width = `${cell}px`;
        g.style.height = `${cell}px`;
        boardEl.appendChild(g);
      }
    }
    for (const bus of Object.values(state.buses)) {
      if (bus.status !== 'board') continue;
      boardEl.appendChild(makeBoardBus(bus));
    }
  }

  function makeBoardBus(bus) {
    const horizontal = bus.dir === 'left' || bus.dir === 'right';
    const el = document.createElement('div');
    el.className = `bus c-${bus.color} dir-${bus.dir}`;
    el.dataset.busId = bus.id;
    el.style.left = `${bus.x * cell}px`;
    el.style.top = `${bus.y * cell}px`;
    el.style.width = `${(horizontal ? bus.len : 1) * cell}px`;
    el.style.height = `${(horizontal ? 1 : bus.len) * cell}px`;
    el.innerHTML = `
      <div class="bus-inner">
        <div class="bus-cab"></div>
        <div class="bus-dots">${dotsHtml(bus.capacity, bus.passengers)}</div>
      </div>
      <div class="bus-cap">${bus.passengers}/${bus.capacity}</div>`;
    el.title = '点击驶出停车场';
    return el;
  }

  /* ---------- 候车队列 ---------- */
  function renderQueue(state) {
    queueEl.innerHTML = '';
    if (state.queue.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'queue-empty';
      empty.textContent = '🎉 乘客已全部上车';
      queueEl.appendChild(empty);
      return;
    }
    state.queue.forEach((p, i) => {
      const el = document.createElement('div');
      el.className = `passenger c-${p.color}${i === 0 ? ' head' : ''}`;
      if (i === 0) el.title = '队首：下一个上车';
      queueEl.appendChild(el);
    });
  }

  /* ---------- 接客位 ---------- */
  function renderSlots(state, opts = {}) {
    slotsEl.innerHTML = '';
    state.slots.forEach((slot) => {
      const s = document.createElement('div');
      s.className = 'slot';
      s.dataset.slot = String(slot.index);
      if (slot.busId == null) {
        s.innerHTML = `<div class="slot-empty">空位</div>`;
      } else {
        const bus = state.buses[slot.busId];
        s.innerHTML = `
          <div class="slot-bus c-${bus.color}${opts.pop === bus.id ? ' pop-in' : ''}"
               data-slot-bus="${bus.id}">
            <div class="bus-dots">${dotsHtml(bus.capacity, bus.passengers)}</div>
            <div class="bus-cap">${bus.passengers}/${bus.capacity}</div>
          </div>`;
      }
      slotsEl.appendChild(s);
    });
  }

  function dotsHtml(capacity, filled) {
    let html = '';
    for (let i = 0; i < capacity; i++) html += `<i${i < filled ? ' class="filled"' : ''}></i>`;
    return html;
  }

  /* ---------- 动画辅助 ---------- */
  function getBoardBus(busId) {
    return boardEl.querySelector(`.bus[data-bus-id="${busId}"]`);
  }

  function getSlotBus(busId) {
    return slotsEl.querySelector(`.slot-bus[data-slot-bus="${busId}"]`);
  }

  function getQueueHead() {
    return queueEl.querySelector('.passenger');
  }

  function bumpSlotBus(busId) {
    const el = getSlotBus(busId);
    if (!el) return;
    el.classList.add('anim-bump');
    setTimeout(() => el.classList.remove('anim-bump'), 320);
  }

  function renderAll(state, level) {
    renderHud(state, level);
    renderBoard(state);
    renderQueue(state);
    renderSlots(state);
  }

  return {
    renderAll,
    renderHud,
    renderBoard,
    renderQueue,
    renderSlots,
    getBoardBus,
    getSlotBus,
    getQueueHead,
    bumpSlotBus,
    boardEl,
    queueEl,
    slotsEl,
    getCellSize: () => cell,
  };
}

/**
 * 控制层：连接核心逻辑与渲染。
 * 职责：
 *  - 关卡流程：开始 / 重开 / 下一关 / 全部通关循环；
 *  - 输入处理：点击巴士 -> moveBus -> 播放事件动画 -> 自动结算；
 *  - 输入锁 locked：动画与结算期间忽略一切点击，防止重复点击、
 *    重复结算与状态错乱；胜负后锁死直到重开/下一关；
 *  - 反馈：被挡摇头 + 挡路车闪烁 + toast 文案。
 *
 * 动画策略：逻辑先行（事件已结算），UI 按「逻辑返回的事件序列」
 * 逐个播放；每个事件播放完成后立即重渲染对应区域进行校准，
 * 保证任何时刻 DOM 与 state 一致。
 */
import {
  initializeLevel,
  moveBus,
  boardPassengers,
  departReady,
  checkWin,
  checkLose,
  loseReason,
} from '../game/logic.js';
import { LEVELS } from '../game/levels.js';
import { createRenderer } from './render.js';

const COLOR_NAMES = {
  red: '红色', blue: '蓝色', green: '绿色', purple: '紫色',
  cyan: '青色', orange: '橙色', yellow: '黄色',
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export function createController() {
  const $ = (id) => document.getElementById(id);
  const renderer = createRenderer();

  let levelIndex = 0;
  let level = LEVELS[0];
  let state = null;
  let locked = true;          // 开始页阶段锁输入
  let pendingRelayout = false;
  let toastTimer = null;
  let overlayPrimaryFn = null;
  let overlaySecondaryFn = null;

  /* ================= 关卡流程 ================= */

  function startLevel(i) {
    levelIndex = i;
    level = LEVELS[i];
    state = initializeLevel(level);
    locked = false;
    pendingRelayout = false;
    hideOverlay();
    $('screen-start').classList.add('hidden');
    $('screen-game').classList.remove('hidden');
    renderer.renderAll(state, level);
  }

  /** 重新开始当前关卡（不刷新页面，重建全新 state）。 */
  function restartLevel() {
    state = initializeLevel(level);
    locked = false;
    pendingRelayout = false;
    hideOverlay();
    renderer.renderAll(state, level);
    toast('本关已重置');
  }

  /** 进入下一关（最后一关之后回到第 1 关，形成完整循环）。 */
  function loadNextLevel() {
    if (levelIndex >= LEVELS.length - 1) startLevel(0);
    else startLevel(levelIndex + 1);
  }

  /* ================= 点击巴士 ================= */

  async function onBusClick(busId) {
    if (locked || !state || state.status !== 'playing') return;
    if (state.buses[busId]?.status !== 'board') return;

    const res = moveBus(state, busId); // 内部先 validateMove
    if (!res.ok) {
      handleIllegalMove(busId, res);
      return;
    }

    locked = true;
    renderer.renderHud(state, level);

    // 1) 驶出棋盘 + 到达接客位
    for (const ev of res.events) {
      if (ev.type === 'exit') await animateExit(ev);
      else if (ev.type === 'arrive') {
        renderer.renderSlots(state, { pop: ev.busId });
        await sleep(300);
      }
    }
    renderer.renderBoard(state); // 校准：移除已驶出的巴士

    // 2) 自动结算：上车 / 发车交替，直到稳定
    await runSettle();

    // 3) 胜负判定（只允许触发一次）
    if (checkWin(state)) {
      await sleep(320);
      showWin();
      return; // locked 保持 true：由覆盖层按钮接管
    }
    if (checkLose(state)) {
      await sleep(320);
      showLose();
      return;
    }

    locked = false;
    if (pendingRelayout) {
      pendingRelayout = false;
      renderer.renderAll(state, level);
    }
  }

  function handleIllegalMove(busId, res) {
    if (res.reason === 'blocked') {
      const busEl = renderer.getBoardBus(busId);
      const blockerEl = renderer.getBoardBus(res.blockerId);
      if (busEl) {
        busEl.classList.remove('anim-shake');
        void busEl.offsetWidth; // 重启动画
        busEl.classList.add('anim-shake');
        setTimeout(() => busEl.classList.remove('anim-shake'), 500);
      }
      if (blockerEl) {
        blockerEl.classList.remove('anim-flash');
        void blockerEl.offsetWidth;
        blockerEl.classList.add('anim-flash');
        setTimeout(() => blockerEl.classList.remove('anim-flash'), 1000);
      }
      const blocker = state.buses[res.blockerId];
      toast(`被${COLOR_NAMES[blocker?.color] || ''}巴士挡住了，先移开它！`);
    } else if (res.reason === 'no-slot') {
      toast('接客位已满！等满载的巴士发车后腾出空位。');
    }
  }

  /* ================= 结算动画 ================= */

  async function runSettle() {
    for (;;) {
      const boardEvs = boardPassengers(state);
      for (const ev of boardEvs) await animateBoard(ev);
      if (boardEvs.length > 0) renderer.renderQueue(state);

      const departEvs = departReady(state);
      for (const ev of departEvs) await animateDepart(ev);
      if (departEvs.length > 0) renderer.renderSlots(state);

      if (boardEvs.length === 0 && departEvs.length === 0) break;
    }
  }

  /** 巴士驶出停车场：沿朝向滑出棋盘。 */
  async function animateExit(ev) {
    const el = renderer.getBoardBus(ev.busId);
    if (!el) return;
    const w = renderer.boardEl.clientWidth;
    const h = renderer.boardEl.clientHeight;
    const dist = {
      right: `translate(${w + 40}px, 0)`,
      left: `translate(${-w - 40}px, 0)`,
      down: `translate(0, ${h + 40}px)`,
      up: `translate(0, ${-h - 40}px)`,
    }[ev.dir];
    el.classList.add('anim-exit');
    el.style.transform = dist;
    await sleep(430);
    el.remove();
  }

  /** 队首乘客飞进接客位的巴士。 */
  async function animateBoard(ev) {
    const qEl = renderer.getQueueHead();
    const slotBusEl = renderer.getSlotBus(ev.busId);
    if (!qEl || !slotBusEl) {
      renderer.renderSlots(state);
      renderer.bumpSlotBus(ev.busId);
      await sleep(180);
      return;
    }
    const from = qEl.getBoundingClientRect();
    const to = slotBusEl.getBoundingClientRect();
    // 把乘客元素提升为 fixed，从原位置飞向目标（避免被容器裁剪）
    qEl.classList.remove('head');
    qEl.classList.add('flying');
    document.body.appendChild(qEl);
    qEl.style.left = `${from.left}px`;
    qEl.style.top = `${from.top}px`;
    void qEl.offsetWidth; // 强制 reflow，确保起点生效
    qEl.style.left = `${to.left + to.width / 2 - from.width / 2}px`;
    qEl.style.top = `${to.top + to.height / 2 - from.height / 2}px`;
    qEl.style.transform = 'scale(.45)';
    qEl.style.opacity = '0';
    await sleep(320);
    qEl.remove();
    // 更新接客位巴士的计数与座位点
    renderer.renderSlots(state);
    renderer.bumpSlotBus(ev.busId);
    await sleep(120);
  }

  /** 满载巴士从接客位发车离场。 */
  async function animateDepart(ev) {
    const el = renderer.getSlotBus(ev.busId);
    if (!el) {
      renderer.renderSlots(state);
      await sleep(200);
      return;
    }
    el.classList.add('anim-depart');
    el.style.transform = 'translateX(150%)';
    el.style.opacity = '0';
    await sleep(460);
    renderer.renderSlots(state);
  }

  /* ================= 胜负覆盖层 ================= */

  function showOverlay({ icon, title, text, primary, secondary }) {
    $('overlay-icon').textContent = icon;
    $('overlay-title').textContent = title;
    $('overlay-text').textContent = text;
    const btnP = $('btn-overlay-primary');
    const btnS = $('btn-overlay-secondary');
    btnP.textContent = primary.label;
    overlayPrimaryFn = primary.fn;
    if (secondary) {
      btnS.classList.remove('hidden');
      btnS.textContent = secondary.label;
      overlaySecondaryFn = secondary.fn;
    } else {
      btnS.classList.add('hidden');
      overlaySecondaryFn = null;
    }
    $('overlay').classList.remove('hidden');
  }

  function hideOverlay() {
    $('overlay').classList.add('hidden');
    overlayPrimaryFn = null;
    overlaySecondaryFn = null;
  }

  function showWin() {
    locked = true;
    const isLast = levelIndex >= LEVELS.length - 1;
    const par = level.solution.par;
    const perfect = state.moveCount <= par;
    const text = isLast
      ? `🎉 你通关了全部 ${LEVELS.length} 关！\n本关操作 ${state.moveCount} 次（参考 ${par} 次）${perfect ? '，达到最优解！' : ''}`
      : `送完了所有乘客！\n本关操作 ${state.moveCount} 次（参考 ${par} 次）${perfect ? '，达到最优解！' : ''}`;
    showOverlay({
      icon: isLast ? '🏆' : '🎉',
      title: isLast ? '全部通关！' : '通关！',
      text,
      primary: { label: isLast ? '再来一轮' : '下一关', fn: loadNextLevel },
      secondary: { label: '再玩本关', fn: restartLevel },
    });
  }

  function showLose() {
    locked = true;
    showOverlay({
      icon: '😵',
      title: '堵死了！',
      text: `${loseReason(state)}\n换个顺序再试试吧。`,
      primary: { label: '重试本关', fn: restartLevel },
    });
  }

  /* ================= 杂项 ================= */

  function toast(msg, ms = 2000) {
    const t = $('toast');
    t.textContent = msg;
    t.classList.remove('hidden');
    t.style.animation = 'none';
    void t.offsetWidth;
    t.style.animation = '';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.add('hidden'), ms);
  }

  /* ================= 初始化 ================= */

  function init() {
    $('btn-start').addEventListener('click', () => startLevel(0));
    $('btn-restart').addEventListener('click', restartLevel);
    $('btn-hint').addEventListener('click', () => {
      if (level) toast(level.hint, 4000);
    });
    $('btn-overlay-primary').addEventListener('click', () => overlayPrimaryFn?.());
    $('btn-overlay-secondary').addEventListener('click', () => overlaySecondaryFn?.());

    renderer.boardEl.addEventListener('click', (e) => {
      const busEl = e.target.closest('.bus');
      if (busEl) onBusClick(busEl.dataset.busId);
    });

    window.addEventListener('resize', () => {
      if (locked) { pendingRelayout = true; return; }
      if (state) renderer.renderAll(state, level);
    });
  }

  return { init };
}

/**
 * 《巴士大疏通》入口
 * 组装：核心逻辑(src/game) 与 渲染/控制(src/ui) 完全分离，
 * 本文件只负责启动控制器。
 */
import { createController } from './ui/controller.js';

createController().init();

