```js
window.__LOG = [];
window.__DONE = false;
(async () => {
  const L = window.__LOG;
  const $ = (id) => document.getElementById(id);
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const state = () => ({
    level: $('hud-level').textContent,
    moves: $('hud-moves').textContent,
    queue: document.querySelectorAll('#queue .passenger').length,
    board: Array.from(document.querySelectorAll('#board .bus')).map((b) => b.dataset.busId),
