    toast: $('toast').classList.contains('hidden') ? '' : $('toast').textContent,
  });
  const click = (sel) => {
    const el = document.querySelector(sel);
    if (!el) { L.push(['MISSING', sel, state()]); return false; }
    el.click(); return true;
  };
  const bus = (id) => '.bus[data-bus-id="' + id + '"]';
  const step = async (label, sels, wait) => {
    for (const s of sels) click(s);
    await sleep(wait || 2600);
    L.push([label, state()]);
  };
  try {
