    await step('L2-solve-2', [bus('r1')]);
    await step('L2-solve-3', [bus('b1')]);
    L.push(['L2-won?', state()]);
    await step('L2-next', ['#btn-overlay-primary']);
    // 第 3 关：死锁
    await step('L3-deadlock-b1', [bus('b1')]);
    L.push(['L3-lose-check', state()]);
    await step('L3-retry', ['#btn-overlay-primary']);
    await step('L3-solve-1', [bus('r1')]);
    await step('L3-solve-2', [bus('g1')]);
    await step('L3-solve-3', [bus('b1')]);
    L.push(['L3-won?', state()]);
    await step('L3-next', ['#btn-overlay-primary']);
    // 第 4 关：死锁
    await step('L4-deadlock-p1', [bus('p1')]);
    await step('L4-deadlock-b1', [bus('b1')]);
    L.push(['L4-lose-check', state()]);
    await step('L4-retry', ['#btn-overlay-primary']);
    await step('L4-solve-1', [bus('b1')]);
    await step('L4-solve-2', [bus('g1')]);
    await step('L4-solve-3', [bus('r1')]);
    await step('L4-solve-4', [bus('p1')]);
    L.push(['L4-won?', state()]);
