(function () {
  var doc = document.getElementById('__mobile_test').contentDocument;
  var btn = doc.getElementById('btn-start');
  if (btn) btn.click();
  var board = doc.getElementById('board');
  var wrap = doc.getElementById('board-wrap');
  var queueBox = doc.getElementById('queue').getBoundingClientRect();
  var slotsBox = doc.getElementById('slots').getBoundingClientRect();
  var hudBox = doc.getElementById('hud').getBoundingClientRect();
  var boardBox = board.getBoundingClientRect();
  return JSON.stringify({
    gameVisible: !doc.getElementById('screen-game').classList.contains('hidden'),
    viewport: { w: doc.documentElement.clientWidth, h: doc.documentElement.clientHeight },
    noHorizOverflow: doc.documentElement.scrollWidth <= doc.documentElement.clientWidth,
    boardPx: { w: board.offsetWidth, h: board.offsetHeight },
    boardFitsWrap: board.offsetWidth <= wrap.clientWidth + 1 && board.offsetHeight <= wrap.clientHeight + 1,
    busCount: doc.querySelectorAll('#board .bus').length,
    hudBottom: Math.round(hudBox.bottom),
    queueTop: Math.round(queueBox.top), queueBottom: Math.round(queueBox.bottom),
    boardTop: Math.round(boardBox.top), boardBottom: Math.round(boardBox.bottom),
    slotsBottom: Math.round(slotsBox.bottom),
    allInsideViewport: slotsBox.bottom <= 780,
    cellSize: Math.round(board.offsetWidth / 5),
    busTapSize: (function () { var b = doc.querySelector('.bus'); var r = b.getBoundingClientRect(); return { w: Math.round(r.width), h: Math.round(r.height) }; })()
  });
})()

