    await ev(`(function(){var el=document.querySelector('.bus[data-bus-id="${id}"]'); if(el) el.click(); return 'ok';})()`);
    await ev(`JSON.stringify(0)`);
  }
  const won = JSON.parse(await ev(`JSON.stringify({won: !document.getElementById('overlay').classList.contains('hidden'), title: document.getElementById('overlay-title').textContent})`));
  out.push(['level-' + lv + '-solved', won]);
  if (lv < 5) await ev(`document.getElementById('btn-overlay-primary').click(); 'next'`);
}
return JSON.stringify(out);

