(function () {
  var board = document.getElementById('board').getBoundingClientRect();
  var wrap = document.getElementById('board-wrap').getBoundingClientRect();
  var queueBox = document.getElementById('queue').getBoundingClientRect();
  var slotsBox = document.getElementById('slots').getBoundingClientRect();
  var all = Array.from(document.querySelectorAll('.bus .bus-inner'));
  var scaleAll082 = all.every(function (n) {
    return Math.abs(n.getBoundingClientRect().width / n.parentElement.getBoundingClientRect().width - 0.82) < 0.02;
  });
  var firstBus = document.querySelector('.bus');
  var fb = firstBus.getBoundingClientRect();
  var fi = firstBus.querySelector('.bus-inner').getBoundingClientRect();
  return JSON.stringify({
    level: document.getElementById('hud-level').textContent,
    busCount: document.querySelectorAll('#board .bus').length,
    scaleAll082: scaleAll082,
    busZone: { w: Math.round(fb.width), h: Math.round(fb.height) },
    bodySize: { w: Math.round(fi.width), h: Math.round(fi.height) },
    layout: {
      queueBottom: Math.round(queueBox.bottom),
      slotsTop: Math.round(slotsBox.top),
      slotsBottom: Math.round(slotsBox.bottom),
      boardTop: Math.round(board.top),
      boardBottom: Math.round(board.bottom),
      viewportH: window.innerHeight
    },
    boardFullyVisible: board.top >= slotsBox.bottom && board.bottom <= window.innerHeight && board.width <= wrap.width + 1
  });
})()

