const TAB = "tab_1131298c-a467-42bf-a9de-95f3e8f3faa3";
async function ev(script) { const r = await tools.browser.evaluate({ tabID: TAB, script }); return r.value; }
const out = [];

// 手机竖屏 iframe 复测（390×780）
await ev(`(function () {
  var f = document.createElement('iframe');
  f.id = '__mobile_test';
  f.style.cssText = 'position:fixed;right:8px;top:8px;width:390px;height:780px;border:2px solid #e11;z-index:99999;background:#fff';
  f.src = 'http://localhost:8080/?fast=1';
  document.body.appendChild(f);
  return 'iframe-added';
})()`);
let ready = false;
for (let i = 0; i < 25; i++) {
  const r = await ev(`(function(){var f=document.getElementById('__mobile_test'); var d=f&&f.contentDocument; return d && d.readyState === 'complete' && d.getElementById('btn-start') ? 'ready' : 'wait';})()`);
  if (r === 'ready') { ready = true; break; }
}
out.push(['iframe-ready', ready]);

const mob = JSON.parse(await ev(`(function () {
  var doc = document.getElementById('__mobile_test').contentDocument;
  doc.getElementById('btn-start').click();
  var board = doc.getElementById('board').getBoundingClientRect();
  var wrap = doc.getElementById('board-wrap').getBoundingClientRect();
  var queueBox = doc.getElementById('queue').getBoundingClientRect();
  var slotsBox = doc.getElementById('slots').getBoundingClientRect();
  var bus = doc.querySelector('.bus');
  var b = bus.getBoundingClientRect();
  var inner = bus.querySelector('.bus-inner').getBoundingClientRect();
  return {
    noHorizOverflow: doc.documentElement.scrollWidth <= doc.documentElement.clientWidth,
    queueToSlotsGap: Math.round(doc.getElementById('slots-area').getBoundingClientRect().top - queueBox.bottom),
    slotsAboveBoard: slotsBox.bottom < board.top,
    boardFullyVisible: board.bottom <= 780 && board.width <= wrap.width + 1,
    cell: Math.round(board.width / 5),
    busZone: { w: Math.round(b.width), h: Math.round(b.height) },
    body: { w: Math.round(inner.width), h: Math.round(inner.height) },
    bodyRatio: +(inner.width / b.width).toFixed(2),
    hudTop: Math.round(doc.getElementById('hud').getBoundingClientRect().top)
  };
})()`));
out.push(['mobile-390x780', mob]);

// 手机端点击交互验证
const mobPlay = JSON.parse(await ev(`(function () {
  var doc = document.getElementById('__mobile_test').contentDocument;
  doc.querySelector('.bus[data-bus-id="b1"]').click();
  return { moves: doc.getElementById('hud-moves').textContent };
})()`) || {});
const mobPlay2 = JSON.parse(await ev(`(function () {
  var doc = document.getElementById('__mobile_test').contentDocument;
  return JSON.stringify({
    moves: doc.getElementById('hud-moves').textContent,
    board: Array.from(doc.querySelectorAll('#board .bus')).map(function (b) { return b.dataset.busId; }),
    slots: doc.getElementById('slots').innerText.replace(/\\s+/g, ' ').trim(),
    queue: doc.querySelectorAll('#queue .passenger').length
  });
})()`));
out.push(['mobile-click', mobPlay2]);

// resize 自适应（390 -> 320）
const mobResize = JSON.parse(await ev(`(function () {
  var f = document.getElementById('__mobile_test');
  var doc = f.contentDocument;
  f.style.width = '320px';
  doc.defaultView.dispatchEvent(new Event('resize'));
  var board = doc.getElementById('board').getBoundingClientRect();
  var inner = doc.querySelector('.bus .bus-inner').getBoundingClientRect();
  var bus = doc.querySelector('.bus').getBoundingClientRect();
  return JSON.stringify({
    boardW: Math.round(board.width), boardH: Math.round(board.height),
    noHorizOverflow: doc.documentElement.scrollWidth <= doc.documentElement.clientWidth,
    bodyRatio: +(inner.width / bus.width).toFixed(2),
    boardFullyVisible: board.bottom <= 780
  });
})()`));
out.push(['mobile-resize-320', mobResize]);

// 清理
await ev(`document.getElementById('__mobile_test').remove(); 'cleaned'`);

// 恢复主 tab 为正常动画模式
await tools.browser.navigate({ tabID: TAB, url: "http://localhost:8080" });
const back = JSON.parse(await ev(`JSON.stringify({startVisible: !document.getElementById('screen-start').classList.contains('hidden')})`));
out.push(['restored-normal-mode', back]);
return JSON.stringify(out);

